/**
 * @typedef {import("./weather/provider")} WeatherProvider
 * @param {WeatherProvider} provider 
 * @param {boolean} force 
 */
function fetch(provider, force) {
    if (!isWatchConnected()) {
        console.log('Skipping weather fetch: no watch connected.');
        return;
    }

    if (app.fetchInProgress) {
        console.log('Skipping weather fetch: another fetch is already in progress.');
        return;
    }

    if (typeof provider.isGeocodeBackoffActive === 'function' && provider.isGeocodeBackoffActive()) {
        console.log('Skipping weather fetch: geocoding is in backoff cooldown.');
        return;
    }

    console.log('Fetching from ' + provider.name);
    app.fetchInProgress = true;
    var fetchStart = Date.now();
    var attempt = incrementFetchAttemptCounter();
    var fetchStatus = {
        time: new Date(),
        id: provider.id,
        name: provider.name
    }
    localStorage.setItem(KEY_LAST_FETCH_ATTEMPT, JSON.stringify(fetchStatus));
    try {
        provider.fetch(
            function() {
                // Sucess, update recent fetch time
                app.fetchInProgress = false;
                localStorage.setItem(KEY_LAST_FETCH_SUCCESS, JSON.stringify(fetchStatus));
                resetFetchAttemptCounter();
                console.log('Successfully fetched weather!');
                maybeTrackWeatherFetch({
                    provider: provider.id,
                    success: true,
                    attempt: attempt,
                    usedGpsCache: provider.usedGpsCache,
                    gpsErrorCode: provider.gpsErrorCode,
                    locationMode: provider.locationMode,
                    countryCode: provider.countryCode,
                    settings: app.settings,
                    watchInfo: app.watchInfo,
                    durationMs: Date.now() - fetchStart
                });
            },
            function(failure) {
                // Failure
                app.fetchInProgress = false;
                console.log('[!] Provider failed to update weather: ' + JSON.stringify(failure));
                var attemptStatus = {
                    time: fetchStatus.time,
                    id: fetchStatus.id,
                    name: fetchStatus.name,
                    error: failure
                };
                localStorage.setItem(KEY_LAST_FETCH_ATTEMPT, JSON.stringify(attemptStatus));
                maybeTrackWeatherFetch({
                    provider: provider.id,
                    success: false,
                    attempt: attempt,
                    usedGpsCache: provider.usedGpsCache,
                    gpsErrorCode: provider.gpsErrorCode,
                    locationMode: provider.locationMode,
                    countryCode: provider.countryCode,
                    error: failure,
                    settings: app.settings,
                    watchInfo: app.watchInfo,
                    durationMs: Date.now() - fetchStart
                });
            },
            force
        )
    }
    catch (e) {
        app.fetchInProgress = false;
        console.log('Weather fetch threw synchronously: ' + e.message);
    }
}

/**
 * Send a weather fetch telemetry event when telemetry is enabled.
 *
 * @param {Object} event Telemetry event details.
 * @returns {void}
 */
function maybeTrackWeatherFetch(event) {
    if (!app.telemetry || app.telemetry.enabled !== true) {
        return;
    }
    app.telemetry.trackWeatherFetch(event || {});
}

function tryFetch(provider) {
    if (needRefresh()) {
        fetch(provider, false);
    };
}

function roundDownMinutes(date, minuteMod) {
    // E.g. with minuteMod=30, 3:52 would roll back to 3:30
    out = new Date(date);
    out.setMinutes(date.getMinutes() - (date.getMinutes() % minuteMod));
    out.setSeconds(0);
    out.setMilliseconds(0);
    return out;
}

function needRefresh() {
    // If the weather has never been fetched
    var lastFetchSuccessString = localStorage.getItem(KEY_LAST_FETCH_SUCCESS);
    if (lastFetchSuccessString === null) {
        return true;
    }
    var lastFetchSuccess = JSON.parse(lastFetchSuccessString);
    if (lastFetchSuccess.time === null) {
        // Just covering all my bases
        return true;
    }
    // If the most recent fetch is more than 30 minutes old
    return (Date.now() - roundDownMinutes(new Date(lastFetchSuccess.time), 30) > 1000 * 60 * 30);
}

import { accountTokenSchema } from "../_shared/account-token.ts";
import { hmacSha256Hex } from "../_shared/hash.ts";
import { createClient } from "@supabase/supabase-js";
import { z } from "zod";

const MAX_BODY_BYTES = 4096;
const MAX_EVENTS_PER_HOUR = 60;

const providerSchema = z.enum(["wunderground", "openweathermap", "openmeteo", "mock"]);
const locationModeSchema = z.enum(["gps", "manual_coordinates", "manual_address"]);

const firmwareSchema = z.object({
  major: z.number().int().nonnegative().optional(),
  minor: z.number().int().nonnegative().optional(),
  patch: z.number().int().nonnegative().optional(),
  suffix: z.string().optional(),
}).strip();

const watchInfoSchema = z.object({
  platform: z.string().nullable().optional(),
  model: z.string().nullable().optional(),
  language: z.string().nullable().optional(),
  firmware: firmwareSchema.optional(),
}).strip();

const settingsSchema = z
  .object({
    temperatureUnits: z.string().optional(),
    dayNightShading: z.boolean().optional(),
    provider: providerSchema.optional(),
    axisTimeFormat: z.string().optional(),
    timeFont: z.string().optional(),
    timeLeadingZero: z.boolean().optional(),
    timeShowAmPm: z.boolean().optional(),
    weekStartDay: z.string().optional(),
    firstWeek: z.string().optional(),
    showQt: z.boolean().optional(),
    vibe: z.boolean().optional(),
    btIcons: z.string().optional(),
    colorTime: z.number().optional(),
    colorToday: z.number().optional(),
    colorSunday: z.number().optional(),
    colorSaturday: z.number().optional(),
    colorUSFederal: z.number().optional(),
  })
  .strip();

const telemetryPayloadSchema = z.object({
  eventType: z.literal("weather_fetch"),
  accountToken: accountTokenSchema,
  watchToken: z.string().nullable().optional(),
  provider: providerSchema,
  success: z.boolean(),
  error: z.string().trim().min(1).max(512).nullable(),
  countryCode: z.string().nullable(),
  settings: settingsSchema.default({}),
  appVersion: z.string().trim().min(1, { message: "invalid_app_version" }),
  buildProfile: z.string().trim().min(1, {
    message: "invalid_build_profile",
  }),
  watchInfo: watchInfoSchema.default({}),
  usedGpsCache: z.boolean().default(false),
  gpsErrorCode: z.number().int().nonnegative().nullable().optional(),
  locationMode: locationModeSchema.nullable().optional(),
  durationMs: z.number().int().nonnegative().nullable().optional(),
  attempt: z.number().int().positive().nullable().optional(),
}).superRefine((payload, ctx) => {
  if (payload.success && payload.error !== null) {
    ctx.addIssue({
      code: z.ZodIssueCode.custom,
      message: "error_must_be_null_on_success",
      path: ["error"],
    });
  }

  if (!payload.success && payload.error === null) {
    ctx.addIssue({
      code: z.ZodIssueCode.custom,
      message: "error_required_on_failure",
      path: ["error"],
    });
  }
});

type TelemetryPayload = z.infer<typeof telemetryPayloadSchema>;

function encodeUtf8(value: string) {
  return new TextEncoder().encode(value);
}

Deno.serve(async (req) => {
  if (req.method !== "POST") {
    return Response.json({ error: "method_not_allowed" }, { status: 405 });
  }

  const contentLength = parseInt(req.headers.get("content-length") || "0", 10);
  if (contentLength > MAX_BODY_BYTES) {
    return Response.json({ error: "payload_too_large" }, { status: 413 });
  }

  const rawBody = await req.text();
  if (encodeUtf8(rawBody).length > MAX_BODY_BYTES) {
    return Response.json({ error: "payload_too_large" }, { status: 413 });
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(rawBody);
  } catch (_error) {
    return Response.json({ error: "invalid_json" }, { status: 400 });
  }

  const payloadResult = telemetryPayloadSchema.safeParse(parsed);
  if (!payloadResult.success) {
    return Response.json({
      error: "invalid_payload",
      detail: payloadResult.error.issues[0]?.message || "invalid_payload",
    }, { status: 400 });
  }

  const payload: TelemetryPayload = payloadResult.data;

  const supabaseUrl = Deno.env.get("SUPABASE_URL");
  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  const telemetryHashSecret = Deno.env.get("TELEMETRY_HASH_SECRET");

  if (!supabaseUrl) {
    throw new Error("SUPABASE_URL is not set");
  }

  if (!serviceRoleKey) {
    throw new Error("SUPABASE_SERVICE_ROLE_KEY is not set");
  }

  if (!telemetryHashSecret) {
    throw new Error("TELEMETRY_HASH_SECRET is not set");
  }

  const supabase = createClient(
    supabaseUrl,
    serviceRoleKey,
  );
  const accountTokenHash = await hmacSha256Hex(
    telemetryHashSecret,
    payload.accountToken,
  );
  const watchTokenHash = payload.watchToken && payload.watchToken.trim() !== ""
    ? await hmacSha256Hex(telemetryHashSecret, payload.watchToken)
    : null;
  const oneHourAgo = new Date(Date.now() - 60 * 60 * 1000).toISOString();

  const rate = await supabase
    .from("telemetry_weather_fetch")
    .select("id", { count: "exact", head: true })
    .eq("account_token_hash", accountTokenHash)
    .gte("received_at", oneHourAgo);

  if (rate.error) {
    return Response.json({ error: "rate_check_failed" }, { status: 500 });
  }

  if ((rate.count || 0) >= MAX_EVENTS_PER_HOUR) {
    return Response.json({ error: "rate_limit_exceeded" }, { status: 429 });
  }

  const insertResult = await supabase.from("telemetry_weather_fetch").insert({
    account_token_hash: accountTokenHash,
    watch_token_hash: watchTokenHash,
    provider: payload.provider,
    success: payload.success,
    error: payload.error,
    country_code: payload.countryCode,
    settings_json: payload.settings,
    app_version: payload.appVersion,
    build_profile: payload.buildProfile,
    watch_info: payload.watchInfo,
    used_gps_cache: payload.usedGpsCache,
    gps_error_code: payload.gpsErrorCode ?? null,
    location_mode: payload.locationMode ?? null,
    duration_ms: payload.durationMs ?? null,
    attempt: payload.attempt ?? null,
  });

  if (insertResult.error) {
    return Response.json({ error: "insert_failed" }, { status: 500 });
  }

  return Response.json({ status: "accepted" }, { status: 202 });
});

